    18	public class WebApplication {
    19	    private final ReservationService reservationService;
    20	    private final MessagingService messagingService;
    21	    private final ReportService reportService;
    22	    private final com.pousadamarealta.repository.RoomRepository roomRepository;
    23	
    24	    public WebApplication(ReservationService reservationService,
    25	                         MessagingService messagingService,
    26	                         ReportService reportService,
