    34	    public Javalin createApp() {
    35	        ObjectMapper mapper = new ObjectMapper()
    36	            .registerModule(new JavaTimeModule())
    37	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    38	
    39	        Javalin app = Javalin.create(config -> {
    40	            config.jsonMapper(new JavalinJackson(mapper, true));
    41	        });
    42	
    43	        app.get("/rooms", ctx -> {
    44	            var rooms = roomRepository.findAll();
    45	            ctx.json(rooms.stream().map(RoomResponse::from).toList());
    46	        });
    47	
    48	        app.post("/reservations", ctx -> {
    49	            try {
    50	                var request = ctx.bodyAsClass(CreateReservationRequest.class);
    51	                validateCreateReservation(request);
    52	
    53	                var reservation = reservationService.createReservation(
    54	                    request.roomNumber(),
    55	                    request.guestName(),
    56	                    request.guestEmail(),
    57	                    request.guestCpf(),
    58	                    request.checkIn(),
    59	                    request.checkOut(),
    60	                    request.guests(),
    61	                    request.ratePlan()
    62	                );
    63	
    64	                ctx.status(201).json(ReservationResponse.from(reservation));
    65	            } catch (ReservationService.InvalidRequestException e) {
    66	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    67	            } catch (ReservationService.RoomNotFoundException e) {
    68	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
    69	            } catch (ReservationService.RoomUnavailableException e) {
    70	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
    71	            } catch (ReservationService.CapacityExceededException e) {
    72	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
    73	            } catch (Exception e) {
    74	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request: " + e.getMessage()));
    75	            }
    76	        });
    77	
    78	        app.get("/reservations/{id}", ctx -> {
    79	            try {
    80	                long id = Long.parseLong(ctx.pathParam("id"));
    81	                var reservation = reservationService.findById(id);
    82	                ctx.json(ReservationResponse.from(reservation));
    83	            } catch (NumberFormatException e) {
    84	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
    85	            } catch (ReservationService.ReservationNotFoundException e) {
    86	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    87	            }
    88	        });
    89	
    90	        app.post("/reservations/{id}/confirmation", ctx -> {
    91	            try {
    92	                long id = Long.parseLong(ctx.pathParam("id"));
    93	                var reservation = reservationService.confirmReservation(id);
    94	                ctx.json(ReservationResponse.from(reservation));
    95	            } catch (NumberFormatException e) {
    96	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
    97	            } catch (ReservationService.ReservationNotFoundException e) {
    98	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    99	            } catch (IllegalStateException e) {
   100	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   101	            }
   102	        });
   103	
