   110	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   111	            } catch (ReservationService.ReservationNotFoundException e) {
   112	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   113	            } catch (IllegalStateException e) {
   114	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   115	            }
   116	        });
   117	
   118	        app.post("/reservations/{id}/check-in", ctx -> {
   119	            try {
   120	                long id = Long.parseLong(ctx.pathParam("id"));
   121	                var reservation = reservationService.checkIn(id);
   122	                ctx.json(ReservationResponse.from(reservation));
   123	            } catch (NumberFormatException e) {
   124	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   125	            } catch (ReservationService.ReservationNotFoundException e) {
   126	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   127	            } catch (IllegalStateException e) {
   128	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   129	            }
   130	        });
   131	
   132	        app.post("/reservations/{id}/check-out", ctx -> {
   133	            try {
   134	                long id = Long.parseLong(ctx.pathParam("id"));
   135	                var reservation = reservationService.checkOut(id);
   136	                var document = reservationService.getDocument(id);
   137	                ctx.json(DocumentResponse.from(document));
   138	            } catch (NumberFormatException e) {
   139	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   140	            } catch (ReservationService.ReservationNotFoundException e) {
   141	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   142	            } catch (IllegalStateException | ReservationService.OperationNotAllowedException e) {
   143	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   144	            }
   145	        });
   146	
   147	        app.get("/reservations/{id}/document", ctx -> {
   148	            try {
   149	                long id = Long.parseLong(ctx.pathParam("id"));
   150	                var document = reservationService.getDocument(id);
   151	                ctx.json(DocumentResponse.from(document));
   152	            } catch (NumberFormatException e) {
   153	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
   154	            } catch (ReservationService.ReservationNotFoundException e) {
   155	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
   156	            } catch (ReservationService.OperationNotAllowedException e) {
   157	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
   158	            }
   159	        });
   160	
   161	        app.get("/messages", ctx -> {
   162	            var messages = messagingService.findAll();
   163	            ctx.json(messages.stream().map(MessageResponse::from).toList());
   164	        });
   165	
   166	        app.get("/reports/occupancy", ctx -> {
   167	            try {
   168	                String dateStr = ctx.queryParam("date");
   169	                if (dateStr == null || dateStr.isBlank()) {
   170	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing 'date' parameter"));
   171	                    return;
   172	                }
   173	
   174	                LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
   175	                String csv = reportService.generateOccupancyReport(date);
   176	                ctx.contentType("text/csv; charset=utf-8").result(csv);
   177	            } catch (DateTimeParseException e) {
   178	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
   179	            }
   180	        });
   181	
   182	        app.get("/reports/revenue", ctx -> {
   183	            try {
   184	                String monthStr = ctx.queryParam("month");
   185	                if (monthStr == null || monthStr.isBlank()) {
   186	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing 'month' parameter"));
   187	                    return;
   188	                }
   189	
   190	                String[] parts = monthStr.split("-");
   191	                if (parts.length != 2) {
   192	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   193	                    return;
   194	                }
   195	
   196	                int year = Integer.parseInt(parts[0]);
   197	                int month = Integer.parseInt(parts[1]);
   198	
   199	                String csv = reportService.generateRevenueReport(year, month);
   200	                ctx.contentType("text/csv; charset=utf-8").result(csv);
   201	            } catch (NumberFormatException e) {
   202	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
   203	            }
   204	        });
   205	
   206	        return app;
   207	    }
   208	
   209	    private void validateCreateReservation(CreateReservationRequest request) {
   210	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
   211	            throw new ReservationService.InvalidRequestException("Missing roomNumber");
   212	        }
   213	        if (request.guestName() == null || request.guestName().isBlank()) {
   214	            throw new ReservationService.InvalidRequestException("Missing guestName");
   215	        }
   216	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
   217	            throw new ReservationService.InvalidRequestException("Missing guestEmail");
   218	        }
   219	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
   220	            throw new ReservationService.InvalidRequestException("Missing guestCpf");
   221	        }
   222	        if (request.checkIn() == null) {
   223	            throw new ReservationService.InvalidRequestException("Missing checkIn");
   224	        }
   225	        if (request.checkOut() == null) {
   226	            throw new ReservationService.InvalidRequestException("Missing checkOut");
   227	        }
   228	        if (request.ratePlan() == null) {
   229	            throw new ReservationService.InvalidRequestException("Missing ratePlan");
   230	        }
   231	    }
   232	}

