     1	package com.pousadamarealta.messaging.rules;
     2	
     3	import com.pousadamarealta.messaging.MessageContext;
     4	import com.pousadamarealta.messaging.MessageRule;
     5	
     6	public class EmailValidationRule implements MessageRule {
     7	
     8	    @Override
     9	    public MessageContext apply(MessageContext context) {
    10	        String email = context.getCurrent().getTo();
    11	
    12	        if (!isValidEmail(email)) {
    13	            return context.withBlocked(true);
    14	        }
    15	
    16	        return context;
    17	    }
    18	
    19	    private boolean isValidEmail(String email) {
    20	        if (email == null || email.isBlank()) {
    21	            return false;
    22	        }
    23	
    24	        long atCount = email.chars().filter(ch -> ch == '@').count();
    25	        if (atCount != 1) {
    26	            return false;
    27	        }
    28	
    29	        int atIndex = email.indexOf('@');
    30	        String localPart = email.substring(0, atIndex);
    31	        String domainPart = email.substring(atIndex + 1);
    32	
    33	        if (localPart.isEmpty()) {
    34	            return false;
    35	        }
    36	
    37	        if (!domainPart.contains(".")) {
    38	            return false;
    39	        }
    40	
    41	        return true;
    42	    }
    43	}
