     1	package com.pousadamarealta.messaging;
     2	
     3	import com.pousadamarealta.domain.Message;
     4	import com.pousadamarealta.domain.MessageStatus;
     5	
     6	import java.util.ArrayList;
     7	import java.util.List;
     8	
     9	public class MessagePipeline {
    10	    private final List<MessageRule> rules;
    11	
    12	    public MessagePipeline(List<MessageRule> rules) {
    13	        this.rules = new ArrayList<>(rules);
    14	    }
    15	
    16	    public ProcessingResult process(MessageRequest request) {
    17	        MessageContext context = new MessageContext(request);
    18	
    19	        for (MessageRule rule : rules) {
    20	            context = rule.apply(context);
    21	            if (context.isBlocked()) {
    22	                break;
    23	            }
    24	        }
    25	
    26	        return buildResult(context);
    27	    }
    28	
    29	    private ProcessingResult buildResult(MessageContext context) {
    30	        List<Message> messages = new ArrayList<>();
    31	
    32	        MessageRequest current = context.getCurrent();
    33	        MessageStatus status = context.isBlocked() ? MessageStatus.BLOCKED : MessageStatus.SENT;
    34	        messages.add(new Message(null, current.getChannel(), current.getTo(),
    35	                                 current.getSubject(), current.getBody(), status));
    36	
    37	        if (!context.isBlocked()) {
    38	            for (MessageRequest additional : context.getAdditional()) {
    39	                messages.add(new Message(null, additional.getChannel(), additional.getTo(),
    40	                                       additional.getSubject(), additional.getBody(), MessageStatus.SENT));
    41	            }
    42	        }
    43	
    44	        return new ProcessingResult(messages);
    45	    }
    46	
    47	    public static class ProcessingResult {
    48	        private final List<Message> messages;
    49	
    50	        public ProcessingResult(List<Message> messages) {
    51	            this.messages = messages;
    52	        }
