    20	    private final BigDecimal total;
    21	
    22	    public ReservationDocument(Reservation reservation) {
    23	        this.reservationId = reservation.getId();
    24	        this.guestName = reservation.getGuestName();
    25	        this.guestCpf = reservation.getGuestCpf();
    26	        this.roomNumber = reservation.getRoomNumber();
    27	        this.roomType = reservation.getRoomType();
    28	        this.checkIn = reservation.getCheckIn();
    29	        this.checkOut = reservation.getCheckOut();
    30	        this.nights = reservation.getNights();
    31	        this.subtotal = reservation.calculateSubtotal();
    32	        this.discount = reservation.calculateDiscount();
    33	        this.total = reservation.calculateTotal();
    34	    }
