    36	    public String formatAsText() {
    37	        StringBuilder sb = new StringBuilder();
    38	        sb.append("Comprovante de reserva nº ").append(reservationId).append("\n");
    39	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(formatCpf(guestCpf)).append(")\n");
    40	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    41	        sb.append("Entrada: ").append(checkIn.format(DATE_FORMATTER))
    42	          .append(" | Saída: ").append(checkOut.format(DATE_FORMATTER))
    43	          .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append("\n");
    44	        sb.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
    45	
    46	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
    47	            sb.append("Desconto: ").append(formatMoney(discount)).append("\n");
    48	        }
    49	
    50	        sb.append("Total: ").append(formatMoney(total));
    51	
    52	        return sb.toString();
    53	    }
    54	
